test("Defer20220824Handler can be used with `ApolloClient`", async () => {

const client = new ApolloClient({
    link: schemaLink,
    cache: new InMemoryCache(),
    incrementalHandler: new Defer20220824Handler(),
  });

const query = gql`
    query HeroNameQuery {
      hero {
        id
        ... @defer {
          name
        }
      }
    }
  `;

const observableStream = new ObservableStream(client.watchQuery({ query }));

  await expect(observableStream).toEmitTypedValue({
    loading: true,
    data: undefined,
    dataState: "empty",
    networkStatus: NetworkStatus.loading,
    partial: true,
  });

  await expect(observableStream).toEmitTypedValue({
    loading: true,
    data: markAsStreaming({
      hero: {
        __typename: "Hero",
        id: "1",
      },
    }),
    dataState: "streaming",
    networkStatus: NetworkStatus.streaming,
    partial: true,
  });

  await expect(observableStream).toEmitTypedValue({
    loading: false,
    data: {
      hero: {
        __typename: "Hero",
        id: "1",
        name: "Luke",
      },
    },
    dataState: "complete",
    networkStatus: NetworkStatus.ready,
    partial: false,
  });
});

test("merges cache updates that happen concurrently", async () => {

const client = new ApolloClient({
    link: stream.httpLink,
    cache: new InMemoryCache(),
    incrementalHandler: new Defer20220824Handler(),
  });

const query = gql`
    query HeroNameQuery {
      hero {
        id
        job
        ... @defer {
          name
        }
      }
    }
  `;

const observableStream = new ObservableStream(client.watchQuery({ query }));

  await expect(observableStream).toEmitTypedValue({
    loading: true,
    data: undefined,
    dataState: "empty",
    networkStatus: NetworkStatus.loading,
    partial: true,
  });

  stream.enqueueInitialChunk({
    data: {
      hero: {
        __typename: "Hero",
        id: "1",
        job: "Farmer",
      },
    },
    hasNext: true,
  });

  await expect(observableStream).toEmitTypedValue({
    loading: true,
    data: markAsStreaming({
      hero: {
        __typename: "Hero",
        id: "1",
        job: "Farmer",
      },
    }),
    dataState: "streaming",
    networkStatus: NetworkStatus.streaming,
    partial: true,
  });

  client.cache.writeFragment({
    id: "Hero:1",
    fragment: gql`
      fragment HeroJob on Hero {
        job
      }
    `,
    data: {
      job: "Jedi",
    },
  });

  stream.enqueueSubsequentChunk({
    incremental: [
      {
        data: {
          name: "Luke",
        },
        path: ["hero"],
      },
    ],
    hasNext: false,
  });

  await expect(observableStream).toEmitTypedValue({
    loading: false,
    data: {
      hero: {
        __typename: "Hero",
        id: "1",
        job: "Jedi", // updated from cache
        name: "Luke",
      },
    },
    dataState: "complete",
    networkStatus: NetworkStatus.ready,
    partial: false,
  });
});

